&reftitle.description;
intfalsefileperms stringfilename
Lee los permisos del fichero dado.

&reftitle.parameters;




   filename



     Ruta de acceso al fichero.

  &reftitle.examples;



    Mostrar los permisos en valor octal


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    Mostrar todos los permisos


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // Pipe FIFO
    case 0x2000: $info = 'c'; break; // Especial de carácter
    case 0x4000: $info = 'd'; break; // Directorio
    case 0x6000: $info = 'b'; break; // Especial de bloque
    case 0x8000: $info = '-'; break; // Regular
    case 0xA000: $info = 'l'; break; // Enlace simbólico (accesible al utilizar la función lstat)
    case 0xC000: $info = 's'; break; // Socket

    // Desconocido
    default: $info = 'u';
}

// Propietario
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Grupo
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Todos
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


-rw-r--r--
